/* Independently generated by Python hashlib.shake_256 and one-bit extraction.
 * SHAKE256 of the 256 bytes (signed coefficient + eta), seed=00,01,...,1f. */
static const char *const kats[10] = {
    "c273f01bdd6a3a00a31a3ac4fec9eb934d4ffe83a31add59fb776117d1d27b49",
    "f4bfeaa2eef31ec192132788e89661bcaa5f873af6af13a6d13c67afd5d87933",
    "4c9a28142fee0bf76c67d0e1c8a887b9baa0102b8f0408810849d0e63f645aba",
    "1d04fc2144b76cb1099bfdb1acaccfbe8db7ea2c83041a2e4fcf18c38d8c56cb",
    "c8c755a6deb864255ce74256f873e019f72b9d6f2f427e5ed36fd83c67ac31a1",
    "56c19964c6de0142bdae2a5fc6dd4768c2cd48af1a93dd894e774c9caab8a6b9",
    "219a1e57d09f7cc8c57f1840caab8b76241e2481629464806b26809aa9eb4272",
    "ad9fcae2eff3064d0828291049aea6b88dc40da03f2c7f6c6b77e843bea06363",
    "12b366039aacacbdb886fe0823dfabee85c26b624a52388199dd6e901b0fde5d",
    "3ff1d7bbc9db5465272925462bab5dccd11eac239aaf5c282e7fa45874976a15"
};

/* Independent Python hashlib/one-bit reference. New KATs hash 16-bit
 * little-endian (coefficient+eta), so tests also cover eta>127. */
static const struct { unsigned eta; const char *digest; } wide_kats[] = {
    {12, "5390951dec74148cf4d12b080dbaf7971daaa6cfc7ca7d7567905080ca7ce4b4"},
    {13, "22f223757cbc6010f59f99ba581f4ff1f38aec6ecb3778e7bfb9f8c05365bf34"},
    {16, "b96e4d0b9106d27327e5526072c7a03d2fa5e1a6d033e316596e99108b115fa3"},
    {17, "2ac3c922f1d7fbbb6b08cb3da54d69df1619753b1a5c8f234744c43b89f41656"},
    {22, "0ca8d552ae10a7e6fdf96a9dae66754db9851ef05ff02b31c009005b7032ec98"},
    {31, "850e56006aee129c2dca0d0614af245708d67e257d69c9c739120da44e67c417"},
    {32, "2b7d7f54a78bb8b664b2377ffb7cba45570ba8260dfc78c7b2012565fbe0f8d6"},
    {63, "e56aca2f83a822eccda0c7f18ed940aa7f819be17d1801661af5945c2f2ad49e"},
    {64, "217f29c7cd3aa952f8793fda92351d80868eef45a22aef1e01245695cc04ca88"},
    {65, "894ae4a0e831e4465f7c14be596742ceef5dc0accda73db81dd995908beaabe1"},
    {66, "32d7eb62acb326789735440a07d01a81c24077331816fdc324bccffa6a91ed37"},
    {127, "e1f64cc51ad99787a3c9b088033adf2ff58a662410d2321c90181662456b76d8"},
    {128, "13e3112c08a6a7eb52d259a87e74ad72c79e81fc3cc3b6f528346738e1932122"},
    {129, "0a06fa4ca935736fd1fb340ef424ade64703d7acd416c1625a2591237302ee28"},
    {257, "9c0d21ec0d4ed6c2ccc739f03a96d190e5918bdcb435187b8fa6eea98315bcb8"}
};

static const char *kat_for(unsigned eta)
{
    size_t i;
    if (eta <= 10) return kats[eta-1];
    for (i = 0; i < sizeof(wide_kats)/sizeof(wide_kats[0]); ++i)
        if (wide_kats[i].eta == eta) return wide_kats[i].digest;
    assert(!"missing CBD KAT");
    return NULL;
}

static void check(unsigned eta, uint64_t q)
{
    uint8_t seed[32], bits[64u*257u], after[64], reference_after[64];
    uint8_t encoded[2u*LBPRE_D], digest[32], expected_digest[32];
    uint64_t out[LBPRE_D];
    lbpre_rng *actual, *reference;
    unsigned i;
    assert(eta >= 1 && eta <= 257);
    for (i = 0; i < sizeof(seed); ++i) seed[i] = (uint8_t)i;
    actual = lbpre_rng_new(seed);
    reference = lbpre_rng_new(seed);
    assert(actual != NULL && reference != NULL);
    lbpre_cbd_poly(out, q, eta, actual);
    lbpre_rng_bytes(reference, bits, 64u * eta);
    for (i = 0; i < LBPRE_D; ++i) {
        unsigned j, pos = 2u * eta * i;
        int value = 0;
        uint64_t expected;
        /* Deliberately bitwise reference, unlike the sampler's packed words. */
        for (j = 0; j < 2u * eta; ++j) {
            int bit = (bits[(pos+j)/8u] >> ((pos+j)%8u)) & 1;
            value += j < eta ? bit : -bit;
        }
        if (value < 0) {
            uint64_t magnitude = (uint64_t)(-value) % q;
            expected = magnitude ? q - magnitude : 0;
        } else expected = (uint64_t)value % q;
        assert(out[i] < q && out[i] == expected);
        if (eta <= 10) encoded[i] = (uint8_t)(value + (int)eta);
        else {
            unsigned shifted = (unsigned)(value + (int)eta);
            encoded[2u*i] = (uint8_t)shifted;
            encoded[2u*i+1u] = (uint8_t)(shifted >> 8);
        }
    }
    shake256(digest, sizeof(digest), encoded, (eta <= 10 ? 1u : 2u)*LBPRE_D);
    for (i = 0; i < sizeof(expected_digest); ++i) {
        unsigned byte;
        assert(sscanf(kat_for(eta) + 2u*i, "%2x", &byte) == 1);
        expected_digest[i] = (uint8_t)byte;
    }
    assert(memcmp(digest, expected_digest, sizeof(digest)) == 0);
    /* Checks that all coefficients use disjoint bits and no bytes leak/reuse
     * into the following random draw. This is sampler-backend independent. */
    lbpre_rng_bytes(actual, after, sizeof(after));
    lbpre_rng_bytes(reference, reference_after, sizeof(reference_after));
    assert(memcmp(after, reference_after, sizeof(after)) == 0);
    lbpre_rng_free(actual);
    lbpre_rng_free(reference);
}

static void distribution_smoke(void)
{
    const uint64_t q = UINT64_C(8708132098049);
    uint8_t seed[32] = {65};
    lbpre_rng *rng = lbpre_rng_new(seed);
    uint64_t out[LBPRE_D];
    long double sum = 0, square_sum = 0;
    unsigned positive = 0, negative = 0, cbd1[3] = {0};
    size_t batch, i;
    const size_t count = 512u*LBPRE_D;
    assert(rng != NULL);
    for (batch = 0; batch < 512; ++batch) {
        lbpre_cbd_poly(out,q,65,rng);
        for (i = 0; i < LBPRE_D; ++i) {
            int64_t x = out[i] <= q/2 ? (int64_t)out[i] : -(int64_t)(q-out[i]);
            assert(x >= -65 && x <= 65);
            sum += x; square_sum += (long double)x*x;
            positive += x > 0; negative += x < 0;
        }
        lbpre_cbd_poly(out,q,1,rng);
        for (i = 0; i < LBPRE_D; ++i) {
            assert(out[i] == 0 || out[i] == 1 || out[i] == q-1);
            ++cbd1[out[i] == q-1 ? 0 : (unsigned)out[i]+1];
        }
    }
    /* Fixed-seed regression checks, not a distribution/security proof. */
    assert(fabsl(sum/count) < 0.06L);
    assert(square_sum/count > 31.7L && square_sum/count < 33.3L);
    assert(positive+1500 > negative && negative+1500 > positive);
    assert(cbd1[0] > 31500 && cbd1[0] < 34000);
    assert(cbd1[1] > 64000 && cbd1[1] < 67000);
    assert(cbd1[2] > 31500 && cbd1[2] < 34000);
    lbpre_rng_free(rng);
}

static void wide_uniform_reference(void)
{
    static const uint64_t moduli[] = {1,3,UINT64_C(265753601),
        UINT64_C(34016143361),UINT64_C(8708132098049),
        UINT64_C(4611686018427387847),UINT64_C(9223372036854775809)};
    uint8_t seed[32] = {43}, bytes[8], after[64], expected_after[64];
    uint64_t out[LBPRE_D];
    size_t i,j;
    for (i = 0; i < sizeof(moduli)/sizeof(moduli[0]); ++i) {
        lbpre_rng *rng = lbpre_rng_new(seed), *ref = lbpre_rng_new(seed);
        uint64_t q = moduli[i];
        assert(rng != NULL && ref != NULL);
        lbpre_uniform_poly(out,q,rng);
        for (j = 0; j < LBPRE_D; ++j) {
            uint64_t x;
            unsigned k;
            do {
                lbpre_rng_bytes(ref,bytes,8);
                x = 0;
                for (k = 0; k < 8; ++k) x |= (uint64_t)bytes[k] << (8u*k);
            } while (x < (UINT64_C(0)-q)%q);
            assert(out[j] < q && out[j] == x%q);
        }
        lbpre_rng_bytes(rng,after,sizeof(after));
        lbpre_rng_bytes(ref,expected_after,sizeof(expected_after));
        assert(memcmp(after,expected_after,sizeof(after)) == 0);
        lbpre_rng_free(rng); lbpre_rng_free(ref);
    }
}

int main(void)
{
    static const uint64_t moduli[] = {1, 2, 3, 17, UINT64_C(1038337),
                                     UINT64_C(4252019713), UINT64_MAX};
    static const unsigned logs[] = {20,30,40};
    size_t i,j;
    unsigned eta;
    for (eta = 1; eta <= 10; ++eta)
        for (i = 0; i < sizeof(moduli)/sizeof(moduli[0]); ++i)
            check(eta, moduli[i]);
    for (j = 0; j < sizeof(wide_kats)/sizeof(wide_kats[0]); ++j)
        for (i = 0; i < sizeof(moduli)/sizeof(moduli[0]); ++i)
            check(wide_kats[j].eta, moduli[i]);
    for (i = 0; i < sizeof(logs)/sizeof(logs[0]); ++i) {
        const lbpre_params *p = lbpre_params_get(logs[i]);
        assert(p != NULL && p->source_eta == 1 && p->internal_eta == 1);
        check(p->terminal_eta,p->q);
    }
    distribution_smoke();
    wide_uniform_reference();
    puts("exact CBD sampler: 25 independent KATs, L/M/H, chunk boundaries through eta257, statistics and 64-bit uniform streams passed");
    return 0;
}
